window.HMC_INFO = {"wn-ginkgo-120":{"noi_dau":["Vừa cầm chìa khoá trên tay mà quay đi đã quên để ở đâu.","Đọc vài trang sách là đầu óc mỏi, khó tập trung như trước.","Tay chân hay lạnh, tê bì mỗi sáng thức dậy làm mình lo lắng."],"cong_dung":["Hỗ trợ tăng cường chức năng nhận thức và trí nhớ ở người lớn.","Góp phần hỗ trợ tuần hoàn ngoại biên, giúp máu lưu thông tới tay chân.","Chiết xuất lá bạch quả chuẩn hoá 24% flavone glycoside và 6% terpene lactone."],"thanh_phan_chinh":"Chiết xuất lá bạch quả 50:1 120 mg/viên (tương đương 6.000 mg lá khô)","lieu_dung":"Người lớn uống 1 viên x 2 lần/ngày hoặc theo chỉ dẫn của bác sĩ. Hỏi ý kiến bác sĩ nếu dùng quá 4 tuần.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc tiểu đường, huyết áp hoặc chống động kinh cần hỏi bác sĩ trước khi dùng.","Không dùng chung với thuốc chống đông, aspirin, ibuprofen, dầu cá hoặc vitamin E vì tăng nguy cơ chảy máu.","Để xa tầm tay trẻ em."]},"wn-omega3-900":{"noi_dau":["Bước sang tuổi bốn mươi, chỉ số mỡ máu trong lần khám gần nhất bắt đầu nhích lên.","Làm việc nhiều, đầu óc dễ mệt và hay quên việc nhỏ trong ngày.","Muốn bổ sung dầu cá mà ngại uống nhiều viên, ợ lên mùi tanh."],"cong_dung":["Hỗ trợ sức khoẻ tim mạch và chức năng não bộ.","Góp phần giảm triglyceride trong máu khi dùng theo liều trên nhãn.","Hỗ trợ cân bằng tâm trạng và quá trình kháng viêm lành mạnh của cơ thể.","Viên bao tan trong ruột, giảm vị tanh dầu cá sau khi uống."],"thanh_phan_chinh":"Omega-3 900 mg/viên (EPA 600 mg, DHA 300 mg) từ 1.425 mg dầu cá cô đặc","lieu_dung":"Người lớn uống 1 viên/ngày để bổ sung omega-3; 2 viên/ngày khi cần hỗ trợ giảm triglyceride hoặc cân bằng tâm trạng, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người dị ứng cá cần đọc kỹ nhãn trước khi dùng.","Để xa tầm tay trẻ em, bảo quản tránh nóng và ẩm."]},"ks-multi-gummy":{"noi_dau":["Bận rộn cả ngày, bữa ăn thất thường nên lo thiếu vitamin mà không biết.","Ngại nuốt viên thuốc to, mua vitamin về rồi để quên trong tủ.","Hay mệt mỏi, dễ ốm vặt mỗi khi thời tiết thay đổi."],"cong_dung":["Bổ sung vitamin và khoáng chất, góp phần duy trì sức khoẻ tốt.","Hỗ trợ chức năng hệ miễn dịch.","Dạng kẹo dẻo làm từ pectin, vị anh đào, cam và quả mọng dễ ăn.","Không chứa sữa, gluten, các loại hạt và gelatin."],"thanh_phan_chinh":"Mỗi viên: vitamin A 306 mcg RAE, vitamin C 20 mg, vitamin D 6,25 mcg, folate 140 mcg, B12 2,15 mcg, kẽm 2,5 mg cùng nhiều vi chất khác","lieu_dung":"Người lớn nhai 2–4 viên, 1 lần/ngày cùng bữa ăn; uống cách các thuốc hoặc sản phẩm sức khoẻ khác vài giờ.","luu_y":["Để xa tầm tay trẻ em; không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Màu kẹo có thể sẫm dần theo thời gian, không ảnh hưởng chất lượng."]},"yt-collagen-390":{"noi_dau":["Soi gương thấy da kém căng, nếp nhăn khoé mắt rõ hơn năm ngoái.","Tóc rụng nhiều, móng tay mỏng và dễ gãy.","Lên xuống cầu thang đầu gối bắt đầu ê ẩm, cứng khớp buổi sáng."],"cong_dung":["Bổ sung collagen thuỷ phân, lượng collagen trong cơ thể giảm dần theo tuổi.","Cung cấp lysine, axit amin góp phần hình thành collagen.","Vitamin C hỗ trợ hình thành mô liên kết.","Hỗ trợ giảm đau khớp liên quan đến thoái hoá khớp."],"thanh_phan_chinh":"Collagen thuỷ phân 6.000 mg và vitamin C 60 mg mỗi khẩu phần 6 viên","lieu_dung":"Người lớn uống 6 viên/ngày, chia 3 viên x 2 lần hoặc uống một lần.","luu_y":["Không dùng cho phụ nữ có thai hoặc đang cho con bú; không dành cho người dưới 18 tuổi.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Sản xuất tại cơ sở có chế biến whey sữa và chiết xuất cá; có thể chứa dư lượng sulfite."]},"eagle-oil":{"noi_dau":["Ngồi máy tính cả ngày, tối về lưng mỏi, vai gáy cứng đơ.","Lỡ trẹo chân, va đập bầm tím mà nhà không có sẵn dầu xoa.","Bố mẹ lớn tuổi hay đau nhức khớp mỗi khi trời trở lạnh."],"cong_dung":["Giảm đau cơ và khớp do đau lưng, căng cơ.","Giảm đau do bầm tím và bong gân.","Mùi thơm the mát, chai nhỏ gọn tiện mang theo."],"thanh_phan_chinh":"Menthol 28,5%, methyl salicylate 18,6%, dầu khuynh diệp 1,56%","lieu_dung":"Người lớn và trẻ từ 13 tuổi trở lên: thoa lên vùng đau 3–4 lần/ngày khi cần.","luu_y":["Chỉ dùng ngoài da, tránh tiếp xúc với mắt; không thoa lên vết thương, da trầy xước, không băng kín hoặc chườm nóng.","Không dùng nếu dị ứng salicylate hoặc đang dùng thuốc chống đông máu.","Ngưng dùng và hỏi bác sĩ nếu triệu chứng nặng hơn, kéo dài quá 7 ngày hoặc nổi mẩn, kích ứng."]},"wn-k2-d3":{"noi_dau":["Bước sang tuổi trung niên, lo xương yếu dần mà không biết bắt đầu từ đâu.","Uống canxi đều đặn nhưng không rõ cơ thể có hấp thu được không.","Ít ra nắng, làm việc trong nhà nên lo thiếu vitamin D."],"cong_dung":["Hỗ trợ hấp thu canxi và phospho.","Góp phần xây dựng và duy trì xương, răng chắc khoẻ.","Hỗ trợ chức năng hệ miễn dịch.","Dùng vitamin K2 dạng MK-7 có hoạt tính sinh học."],"thanh_phan_chinh":"Vitamin K2 (MK-7) 120 mcg và vitamin D3 1.000 IU (25 mcg)/viên","lieu_dung":"Người lớn uống 1 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu cần hỏi ý kiến bác sĩ trước khi dùng.","Để xa tầm tay trẻ em; bảo quản tránh nóng, ánh sáng và độ ẩm."]},"glucerna":{"noi_dau":["Bố mẹ bị tiểu đường, bữa nào cũng phải cân nhắc ăn gì để đường huyết ổn.","Bữa sáng vội vàng, không có món nào vừa no vừa yên tâm cho người tiểu đường.","Người lớn tuổi ăn kém, lo thiếu chất nhưng ngại đồ uống nhiều đường."],"cong_dung":["Dinh dưỡng đầy đủ, cân đối dành cho người tiểu đường.","Dùng carbohydrate chỉ số đường huyết thấp, hỗ trợ hạn chế tăng đường huyết sau uống.","Mỗi chai cung cấp 11 g đạm, 5,6 g chất xơ và 26 vitamin, khoáng chất.","Có thể dùng thay một bữa ăn hoặc bữa phụ."],"thanh_phan_chinh":"Mỗi chai 237 ml: đạm 11 g, chất xơ 5,6 g, 26 vitamin và khoáng chất","lieu_dung":"Lắc đều trước khi uống, ngon hơn khi uống lạnh; dùng thay bữa ăn hoặc bữa phụ theo tư vấn của bác sĩ, chuyên gia dinh dưỡng. Sau khi mở nắp, đậy kín, bảo quản tủ lạnh và dùng trong 48 giờ.","luu_y":["Không dùng cho người bị bệnh galactosemia; không dùng đường tĩnh mạch.","Không dành cho trẻ em trừ khi có chỉ định của bác sĩ; người tiểu đường nên trao đổi với bác sĩ về chế độ ăn."]},"wn-super-sleep":{"noi_dau":["Nằm trằn trọc cả tiếng đồng hồ mà mắt vẫn mở thao láo.","Làm ca đêm, lệch múi giờ, nhịp ngủ đảo lộn mấy ngày chưa lại.","Đầu óc căng thẳng, khó thả lỏng để đi vào giấc ngủ."],"cong_dung":["Hỗ trợ rút ngắn thời gian đi vào giấc ngủ.","Góp phần điều chỉnh lại chu kỳ thức – ngủ.","Hỗ trợ tăng tổng thời gian ngủ khi làm ca hoặc lệch múi giờ.","Hỗ trợ thư giãn tạm thời nhờ L-theanine."],"thanh_phan_chinh":"Melatonin 2,5 mg, L-theanine 100 mg, 5-HTP 15 mg/viên nhai","lieu_dung":"Người lớn nhai 1–2 viên/ngày cùng thức ăn, vào hoặc trước giờ đi ngủ (để thư giãn: 2 viên). Hỏi ý kiến bác sĩ nếu dùng quá 4 tuần.","luu_y":["Không dùng cho phụ nữ có thai, đang cho con bú hoặc người bị xơ cứng bì.","Hỏi bác sĩ trước khi dùng nếu đang dùng thuốc chống trầm cảm, thuốc chống đông, thuốc huyết áp, thuốc an thần hoặc có bệnh tim, gan, thận, tiểu đường.","Không lái xe, vận hành máy móc trong 5 giờ sau khi dùng; tránh rượu bia."]},"ocuvite-50-150":{"noi_dau":["Ngoài năm mươi, nhìn chữ nhỏ phải đưa ra xa mới đọc được.","Dùng điện thoại, xem tivi lâu là mắt mỏi, khô và nhoè.","Lo đôi mắt kém dần theo tuổi mà không biết chăm sóc thế nào."],"cong_dung":["Hỗ trợ bảo vệ sức khoẻ mắt cho người từ 50 tuổi.","Lutein và zeaxanthin góp phần tăng cường sắc tố hoàng điểm, hỗ trợ lọc ánh sáng xanh.","Bổ sung omega-3, vitamin C, E, kẽm, đồng và vitamin D.","Viên mềm cỡ nhỏ, dễ uống, chỉ 1 viên mỗi ngày."],"thanh_phan_chinh":"Mỗi viên: vitamin C 150 mg, vitamin E 20 mg, kẽm 9 mg, đồng 1 mg, vitamin D 30 mcg cùng lutein, zeaxanthin và omega-3","lieu_dung":"Uống 1 viên/ngày vào buổi sáng, trong bữa ăn, với một cốc nước đầy.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Để xa tầm tay trẻ em."]},"nb-zinc-50":{"noi_dau":["Cả nhà thay nhau cảm cúm, đứa này vừa khỏi đứa kia lại ốm.","Ăn uống thất thường, lo cơ thể thiếu vi chất mà không hay biết.","Da dễ nổi mụn, vết xước lâu lành hơn trước."],"cong_dung":["Hỗ trợ chức năng hệ miễn dịch.","Bổ sung kẽm, khoáng chất cần thiết cho nhiều hoạt động của cơ thể.","Kẽm gluconate hàm lượng cao, không biến đổi gen, không gluten, phù hợp người ăn chay."],"thanh_phan_chinh":"Kẽm (dạng zinc gluconate) 50 mg/viên","lieu_dung":"Người lớn uống 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Ngưng dùng và hỏi bác sĩ nếu có tác dụng phụ; để xa tầm tay trẻ em."]},"ks-vitc-chew":{"noi_dau":["Thời tiết giao mùa, cả nhà lại sụt sịt, hắt hơi liên tục.","Ngại nuốt viên to nên bỏ dở vitamin giữa chừng.","Ít ăn rau quả, lo thiếu vitamin C mà không để ý."],"cong_dung":["Hỗ trợ hệ miễn dịch.","Hỗ trợ hoạt động chống oxy hoá của cơ thể.","Viên nhai vị cam dễ dùng, đạt chứng nhận USP Verified."],"thanh_phan_chinh":"Vitamin C 500 mg/viên nhai","lieu_dung":"Người lớn nhai 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Để xa tầm tay trẻ em.","Người đang mang thai, cho con bú hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng."]},"ntruth-acv-gummy":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút.","Muốn thử giấm táo nhưng không uống nổi vị chua gắt.","Sau bữa ăn hay đầy bụng, khó tiêu, người nặng nề."],"cong_dung":["Bổ sung giấm táo hữu cơ ở dạng kẹo dẻo, không còn vị chua gắt.","Góp phần hỗ trợ tiêu hoá khi kết hợp chế độ ăn hợp lý.","Đạt chứng nhận hữu cơ USDA, thuần chay, không gluten, không biến đổi gen."],"thanh_phan_chinh":"Giấm táo hữu cơ 500 mg mỗi khẩu phần 2 viên kẹo","lieu_dung":"Người lớn dùng 2 viên kẹo/ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"ks-vite-500":{"noi_dau":["Da khô, kém mịn màng dù đã dùng đủ loại kem dưỡng.","Bước sang tuổi trung niên, lo cơ thể lão hoá nhanh hơn.","Hay mệt mỏi, dễ ốm, muốn bổ sung vi chất mà sợ uống sai."],"cong_dung":["Hỗ trợ hệ miễn dịch và hoạt động chống oxy hoá.","Vitamin E là dưỡng chất thiết yếu cho nhiều tế bào, trong đó có tế bào cơ tim.","Đạt chứng nhận USP Verified, lọ lớn dùng được lâu."],"thanh_phan_chinh":"Vitamin E (dl-alpha tocopheryl acetate) 180 mg (400 IU)/viên","lieu_dung":"Người lớn uống 1 viên/ngày, tốt nhất cùng bữa ăn.","luu_y":["Người đang mang thai, cho con bú, đang dùng thuốc (đặc biệt thuốc chống đông) nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-k2-120":{"noi_dau":["Uống canxi mấy năm mà vẫn lo xương không chắc lên.","Tuổi càng cao, sợ loãng xương, té ngã là gãy xương.","Muốn chăm xương cho mẹ lớn tuổi nhưng không biết bổ sung gì thêm."],"cong_dung":["Hỗ trợ duy trì xương chắc khoẻ.","Giúp phòng ngừa thiếu vitamin K, góp phần duy trì sức khoẻ tốt.","Vitamin K2 dạng MK-7 từ đậu natto, viên nang chay."],"thanh_phan_chinh":"Vitamin K2 (MK-7, từ đậu natto) 120 mcg/viên","lieu_dung":"Người lớn uống 1 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu cần hỏi ý kiến bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"ks-coq10-100":{"noi_dau":["Leo vài tầng cầu thang đã thấy hụt hơi, tim đập nhanh.","Đang uống thuốc mỡ máu, nghe nói cơ thể dễ thiếu CoQ10.","Hay đau nửa đầu, kèm buồn nôn làm gián đoạn công việc."],"cong_dung":["Hỗ trợ sức khoẻ tim mạch.","Là chất chống oxy hoá, góp phần duy trì sức khoẻ tốt.","Khi dùng dự phòng, hỗ trợ giảm tần suất đau nửa đầu và buồn nôn, nôn đi kèm.","CoQ10 nguồn gốc tự nhiên, viên mềm bao tan trong ruột."],"thanh_phan_chinh":"Coenzyme Q10 100 mg/viên","lieu_dung":"Người lớn uống 1 viên x 2–3 lần/ngày hoặc theo chỉ dẫn của bác sĩ; dùng ít nhất 3 tháng để thấy lợi ích.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc chống đông hoặc thuốc huyết áp cần hỏi bác sĩ trước khi dùng.","Gặp bác sĩ nếu đau nửa đầu xuất hiện thường xuyên hơn hoặc buồn nôn kéo dài.","Để xa tầm tay trẻ em."]},"wn-omega369-280":{"noi_dau":["Chế độ ăn ít cá, ít hạt, lo thiếu chất béo tốt cho tim.","Da khô, tóc xơ dù đã dưỡng đủ đường.","Muốn một loại dầu cá dùng được cho cả nhà mà vẫn tiết kiệm."],"cong_dung":["Bổ sung axit béo thiết yếu omega-3, 6 và 9.","Hỗ trợ sức khoẻ tim mạch và não bộ.","Góp phần hỗ trợ hệ thần kinh và duy trì sức khoẻ tốt.","Kết hợp dầu cá, dầu hạt lanh và dầu hạt lưu ly cân đối."],"thanh_phan_chinh":"Mỗi viên: dầu cá 400 mg (EPA 70 mg, DHA 45 mg), dầu hạt lanh 400 mg, dầu hạt lưu ly 400 mg (GLA 75 mg)","lieu_dung":"Người lớn uống 1 viên x 3 lần/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Người đang dùng thuốc chống đông máu nên hỏi bác sĩ trước khi dùng.","Để xa tầm tay trẻ em."]},"sesame-omega3":{"noi_dau":["Con kén ăn cá, mẹ lo bé thiếu DHA cho giai đoạn đang lớn.","Cho con uống dầu cá, bé chê tanh rồi nhè ra.","Muốn con tập trung học tốt hơn mà không biết bổ sung gì an toàn."],"cong_dung":["Bổ sung omega-3, trong đó chủ yếu là DHA cho trẻ.","Góp phần duy trì sức khoẻ tốt, tạo thói quen bổ sung dưỡng chất cho bé.","Kẹo dẻo vị cam chanh, hình Elmo, không gelatin, không màu và chất bảo quản nhân tạo."],"thanh_phan_chinh":"Mỗi viên: omega-3 50 mg (EPA 8 mg, DHA 42 mg) từ 88 mg dầu cá cơm/cá mòi","lieu_dung":"Trẻ từ 3–11 tuổi và 12–17 tuổi: nhai 2 viên/ngày hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Để xa tầm tay trẻ em, người lớn cất giữ và chia viên cho bé.","Sản phẩm có nguồn gốc từ cá, trẻ dị ứng cá cần hỏi bác sĩ trước khi dùng."]},"olay-fresh-radiance":{"noi_dau":["Tắm xong da khô căng, phải thoa kem dưỡng ngay mới dễ chịu.","Mùi sữa tắm bay nhanh, chưa hết buổi sáng đã không còn thơm.","Muốn một chai sữa tắm dùng chung cả nhà, dịu nhẹ mà dùng được lâu."],"cong_dung":["Làm sạch dịu nhẹ với chất tẩy rửa nguồn gốc thực vật.","Bổ sung phức hợp vitamin B3 và chất chống oxy hoá, giúp da mềm mại sau tắm.","Hương thơm tươi mát lưu lâu, có hai mùi hoa hồng và oải hương.","Không chứa paraben và phthalate; chai 887 ml có vòi bơm tiện dùng."],"thanh_phan_chinh":"Phức hợp vitamin B3 và chất chống oxy hoá","lieu_dung":"Cho một lượng vừa đủ ra bông tắm hoặc lòng bàn tay, tạo bọt, mát-xa khắp cơ thể rồi tắm sạch lại với nước. Dùng hằng ngày.","luu_y":["Tránh để sản phẩm dính vào mắt; nếu dính, rửa kỹ bằng nước sạch."]},"lv-belt-damier":{"noi_dau":["Muốn sắm một chiếc thắt lưng hàng hiệu mà sợ mua phải hàng không chuẩn.","Phân vân giữa kiểu dáng thời thượng và món đồ dùng được lâu năm.","Chọn quà cho chồng, bố mà lo không hợp gu, không hợp trang phục."],"cong_dung":["Mặt canvas hoạ tiết ô bàn cờ Damier Ébène nâu đặc trưng của Louis Vuitton.","Khoá chữ LV Initiales kim loại màu bạc, nổi bật mà vẫn lịch sự.","Thiết kế hai mặt: một mặt canvas Damier, một mặt da trơn, đổi phong cách dễ dàng.","Hợp cả quần âu công sở lẫn quần jeans dạo phố."],"lieu_dung":"Cắt hoặc chỉnh độ dài phù hợp vòng eo tại cửa hàng chuyên về đồ da. Sau khi dùng, lau khô, cất vào túi vải hoặc hộp kèm theo, tránh để nơi ẩm, nắng gắt và tránh tiếp xúc nước, nước hoa."},"nb-melatonin-gummy":{"noi_dau":["Nằm trằn trọc cả tiếng đồng hồ mà mắt vẫn mở thao láo.","Đi công tác, lệch múi giờ là mấy hôm liền ngủ chập chờn.","Không muốn dùng thuốc ngủ nhưng cũng cần một giấc ngủ yên."],"cong_dung":["Hỗ trợ cải thiện chất lượng giấc ngủ theo công bố trên nhãn.","Góp phần giúp điều chỉnh lại nhịp thức – ngủ của cơ thể.","Hỗ trợ giảm ảnh hưởng của lệch múi giờ khi đi xa.","Dạng kẹo dẻo vị dâu, dễ dùng cho người ngại nuốt viên."],"thanh_phan_chinh":"Melatonin 2,5 mg/viên kẹo (5 mg mỗi liều 2 viên)","lieu_dung":"Người lớn: nhai 2 viên, 1 lần/ngày, vào lúc hoặc trước giờ đi ngủ. Khi lệch múi giờ: dùng 2 viên trước khi ngủ trong chuyến đi và tại nơi đến cho tới khi cơ thể quen giờ mới.","luu_y":["Không dùng cho phụ nữ có thai hoặc đang cho con bú.","Hỏi bác sĩ nếu đang dùng thuốc chống đông, thuốc huyết áp, thuốc an thần, thuốc chống co giật hoặc có bệnh gan, thận, trầm cảm, tiểu đường.","Không dùng cùng rượu; mất ngủ kéo dài quá 4 tuần nên đi khám."]},"wn-zinc-50":{"noi_dau":["Cả nhà hay ốm vặt mỗi lần trời trở gió.","Da dễ nổi mụn, vết xước lâu lành hơn trước.","Ăn uống thất thường, sợ cơ thể thiếu khoáng chất mà không biết."],"cong_dung":["Bổ sung kẽm dạng citrate, dạng hấp thu tốt.","Hỗ trợ duy trì chức năng miễn dịch bình thường.","Góp phần duy trì làn da, tóc, móng và xương khỏe mạnh.","Hỗ trợ chuyển hóa năng lượng và hình thành mô."],"thanh_phan_chinh":"Kẽm 50 mg/viên (dạng kẽm citrate)","lieu_dung":"Người lớn: uống 1 viên/ngày cùng bữa ăn, cách các thuốc khác vài giờ, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Bổ sung kẽm có thể gây thiếu đồng; nếu không chắc lượng đồng đang dùng, hỏi nhân viên y tế trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-mag-citrate":{"noi_dau":["Hay bị chuột rút bắp chân, nhất là lúc nửa đêm.","Cơ thể mỏi mệt, căng cứng dù chẳng làm việc gì nặng.","Tuổi càng lớn càng lo xương khớp và tim không còn khỏe như trước."],"cong_dung":["Bổ sung magie dạng citrate, 150 mg magie nguyên tố mỗi viên.","Hỗ trợ duy trì chức năng cơ bình thường, kể cả cơ tim.","Góp phần phát triển và duy trì xương, răng chắc khỏe.","Hỗ trợ cơ thể chuyển hóa dưỡng chất và hình thành mô."],"thanh_phan_chinh":"Magie nguyên tố 150 mg/viên (dạng magie citrate)","lieu_dung":"Người lớn: uống 1–3 viên/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Một số người có thể bị tiêu chảy.","Để xa tầm tay trẻ em, tránh nơi nóng ẩm."]},"jms-cal-mag-d3":{"noi_dau":["Sau tuổi 40, đầu gối bắt đầu kêu lục cục khi leo cầu thang.","Mẹ lớn tuổi đi lại chậm, cả nhà lo chuyện loãng xương.","Ít uống sữa, ít ra nắng, sợ thiếu canxi mà không hay."],"cong_dung":["Bổ sung canxi và magie theo tỷ lệ 2:1 kèm vitamin D3.","Hỗ trợ phát triển và duy trì xương, răng chắc khỏe.","Vitamin D3 hỗ trợ hấp thu và sử dụng canxi, phốt pho.","Magie góp phần duy trì chức năng cơ bình thường, kể cả cơ tim.","Cùng chế độ ăn và vận động hợp lý, góp phần giảm nguy cơ loãng xương về sau."],"thanh_phan_chinh":"Canxi 333 mg, magie 167 mg, vitamin D3 200 IU mỗi viên","lieu_dung":"Người lớn: uống 1–3 viên/ngày cùng bữa ăn, cách các thuốc hoặc thực phẩm bổ sung khác vài giờ.","luu_y":["Một số người có thể bị tiêu chảy.","Phụ nữ có thai, cho con bú nên hỏi nhân viên y tế trước khi dùng.","Để xa tầm tay trẻ em."]},"wn-melatonin-5":{"noi_dau":["Đêm nào cũng nằm đếm giờ, càng cố ngủ càng tỉnh.","Làm ca, giờ giấc đảo lộn khiến giấc ngủ không còn sâu.","Sáng dậy mệt rũ vì cả đêm ngủ chập chờn."],"cong_dung":["Hỗ trợ rút ngắn thời gian đi vào giấc ngủ.","Góp phần điều chỉnh lại nhịp thức – ngủ của cơ thể.","Hỗ trợ tăng tổng thời gian ngủ khi làm ca hoặc lệch múi giờ.","Viên ngậm tan nhanh dưới lưỡi, vị bạc hà dễ chịu."],"thanh_phan_chinh":"Melatonin 5 mg/viên ngậm dưới lưỡi","lieu_dung":"Người lớn: ngậm 1–2 viên dưới lưỡi cho tan, 1 lần/ngày, chỉ dùng trước khi đi ngủ, hoặc theo chỉ dẫn của bác sĩ. Dùng quá 4 tuần nên hỏi bác sĩ.","luu_y":["Không dùng khi có thai, đang cho con bú hoặc đang dùng thuốc ức chế miễn dịch.","Hỏi bác sĩ nếu đang dùng thuốc huyết áp, thuốc an thần, hoặc có bệnh gan, thận, tiểu đường, động kinh, trầm cảm.","Không lái xe, vận hành máy móc trong 5 giờ sau khi dùng."]},"salonpas-140":{"noi_dau":["Ngồi máy tính cả ngày, vai gáy cứng đơ không quay nổi.","Bê đồ nặng một chút là lưng ê ẩm mấy hôm.","Bố mẹ đau khớp mỗi khi trở trời, cần thứ dán tiện mang theo."],"cong_dung":["Giảm tạm thời đau nhức cơ và khớp theo chỉ định trên nhãn.","Dùng cho đau lưng thông thường, cứng vai, căng cơ, bong gân.","Dùng cho vết bầm và đau do viêm khớp.","Hiệu quả kéo dài đến 8 giờ mỗi miếng dán."],"thanh_phan_chinh":"Methyl salicylate 10%, menthol 6%, camphor 3%","lieu_dung":"Người lớn và trẻ từ 12 tuổi: làm sạch, lau khô vùng đau rồi dán, không quá 2 miếng một lần, 1–2 lần/ngày; không để miếng dán trên da quá 8 giờ. Trẻ dưới 12 tuổi cần người lớn giám sát.","luu_y":["Không dán lên vết thương, da trầy xước hoặc kích ứng; không dùng cùng túi chườm nóng vì có thể gây bỏng.","Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú hoặc đang dùng thuốc chống đông.","Ngừng dùng và đi khám nếu đau, sưng, phồng rộp da hoặc triệu chứng kéo dài quá 7 ngày."]},"ensure-regular":{"noi_dau":["Bố mẹ lớn tuổi ăn ít, bữa cơm chỉ vài thìa là buông đũa.","Người mới ốm dậy mệt mỏi, chẳng muốn ăn gì.","Bận rộn bỏ bữa liên tục, lo cơ thể thiếu chất."],"cong_dung":["Bổ sung dinh dưỡng giúp duy trì năng lượng và sự năng động.","Mỗi chai cung cấp 9 g đạm và 240 Calo.","Bổ sung 27 vitamin và khoáng chất theo hộp.","Kẽm, vitamin A, C, D góp phần hỗ trợ hệ miễn dịch.","Không chứa gluten, phù hợp người không dung nạp lactose."],"thanh_phan_chinh":"Mỗi chai 235 ml: 9 g đạm, 240 Calo, 27 vitamin và khoáng chất","lieu_dung":"Uống như một bữa phụ giữa các bữa ăn hoặc dùng kèm bữa ăn. Lắc đều trước khi uống, ngon hơn khi uống lạnh.","luu_y":["Là thực phẩm bổ sung dinh dưỡng, không thay thế tư vấn của nhân viên y tế; người đang theo chế độ ăn bệnh lý nên hỏi bác sĩ."]},"tn-ginkgo-340":{"noi_dau":["Vừa đặt chìa khóa xuống đã quên mất để ở đâu.","Làm việc căng thẳng, đầu óc hay lơ mơ, khó tập trung.","Bố mẹ có tuổi hay quên trước quên sau, con cái lo lắng."],"cong_dung":["Bổ sung chiết xuất lá bạch quả tiêu chuẩn hóa.","Hỗ trợ trí nhớ và khả năng tập trung theo công bố của hãng.","Góp phần hỗ trợ tuần hoàn, lưu thông máu lên não.","Viên nang mềm dễ uống, lọ lớn dùng được lâu."],"thanh_phan_chinh":"Chiết xuất lá bạch quả (Ginkgo biloba) 120 mg/viên","lieu_dung":"Người lớn: uống 1 viên x 2 lần/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc (đặc biệt thuốc chống đông) hoặc sắp phẫu thuật.","Không dành cho người dưới 18 tuổi."]},"ocuvite-50-90":{"noi_dau":["Qua tuổi 50, đọc chữ nhỏ phải đưa ra xa mới thấy.","Nhìn điện thoại một lúc là mắt mỏi, khô và nhòe.","Lo đôi mắt bố mẹ ngày càng kém mà chưa biết bổ sung gì."],"cong_dung":["Bổ sung lutein và zeaxanthin hỗ trợ sắc tố hoàng điểm.","Omega-3 góp phần duy trì nước mắt và võng mạc khỏe mạnh.","Bổ sung vitamin C, E, kẽm, đồng hỗ trợ chống oxy hóa.","Có thêm vitamin D, viên nhỏ dễ nuốt."],"thanh_phan_chinh":"Lutein 5 mg, zeaxanthin 1 mg, omega-3 250 mg, vitamin D 30 mcg mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày vào buổi sáng, cùng bữa ăn với một ly nước đầy.","luu_y":["Để xa tầm tay trẻ em.","Không dùng nếu niêm phong dưới nắp bị rách hoặc mất."]},"sr-omega3-alaskan":{"noi_dau":["Ăn cá biển không thường xuyên, sợ thiếu omega-3.","Uống dầu cá loại thường hay bị ợ tanh khó chịu.","Muốn chăm sóc tim mạch cho cả nhà mà ngại uống nhiều viên."],"cong_dung":["Bổ sung omega-3 hàm lượng cao, 1040 mg mỗi viên.","Hỗ trợ sức khỏe tim mạch và hệ miễn dịch theo công bố của hãng.","Dầu cá minh thái Alaska đánh bắt tự nhiên, đạt chứng nhận MSC.","Chỉ cần 1 viên mỗi ngày."],"thanh_phan_chinh":"Dầu cá 1250 mg/viên, trong đó omega-3 1040 mg (EPA 690 mg, DHA 260 mg)","lieu_dung":"Người lớn: uống 1 viên/ngày cùng bữa ăn, hoặc theo chỉ dẫn của nhân viên y tế.","luu_y":["Hỏi nhân viên y tế trước khi dùng nếu có thai, cho con bú, đang dùng thuốc chống đông hoặc sắp phẫu thuật.","Có chứa cá; không dùng quá liều khuyến nghị."]},"olay-regenerist-set":{"noi_dau":["Soi gương thấy nếp nhăn khóe mắt ngày một rõ.","Da khô, xỉn màu, trang điểm không còn ăn phấn như trước.","Muốn chăm da kỹ hơn nhưng không có thời gian đi spa."],"cong_dung":["Niacinamide và hyaluronic acid giúp cấp ẩm, làm sáng da.","Peptide và vitamin E giúp làm mờ nếp nhăn, rãnh nhăn nhỏ.","Giúp da trông săn chắc, mịn và đều màu hơn.","Hỗ trợ củng cố hàng rào ẩm của da."],"thanh_phan_chinh":"Niacinamide (B3), sodium hyaluronate, peptide (palmitoyl pentapeptide-4), vitamin E, panthenol","lieu_dung":"Sau khi làm sạch da, lấy lượng vừa đủ thoa đều lên mặt và cổ, sáng và tối. Ban ngày nên dùng thêm kem chống nắng.","luu_y":["Có hương liệu; da nhạy cảm nên thử trên một vùng da nhỏ trước.","Tránh tiếp xúc với mắt."]},"yt-collagen-liquid":{"noi_dau":["Da mất dần độ căng, nếp nhăn xuất hiện lúc nào không hay.","Tóc rụng nhiều, móng tay mỏng và dễ gãy.","Muốn bổ sung collagen nhưng ngại pha bột mỗi sáng."],"cong_dung":["Bổ sung 5.000 mg collagen thủy phân mỗi gói, trong đó có Verisol.","Hỗ trợ làn da, tóc và móng khỏe đẹp theo công bố của hãng.","Góp phần cải thiện độ đàn hồi và làm mờ nếp nhăn.","Dạng nước uống liền, không đường, tiện mang theo."],"thanh_phan_chinh":"Collagen 5.000 mg/gói 30 ml (Verisol 2.500 mg + collagen peptide thủy phân 2.500 mg)","lieu_dung":"Người lớn: lắc đều, uống trực tiếp 1 gói mỗi ngày.","luu_y":["Không dùng khi có thai hoặc đang cho con bú; không dành cho người dưới 18 tuổi.","Hỏi bác sĩ nếu đang dùng thuốc hoặc có bệnh lý; không dùng quá liều khuyến nghị."]},"vp-collagen-gummy":{"noi_dau":["Bước qua tuổi 35, da không còn căng mịn như xưa.","Biết collagen tốt nhưng không quen uống bột hay nước.","Muốn chăm da từ bên trong bằng cách đơn giản, dễ duy trì."],"cong_dung":["Bổ sung 2,5 g collagen peptide Verisol mỗi khẩu phần.","Hỗ trợ làm mờ nếp nhăn và rãnh nhăn nhỏ theo công bố của hãng.","Góp phần cải thiện sức khỏe làn da khi dùng đều đặn.","Dạng kẹo dẻo vị mâm xôi, dễ dùng hằng ngày."],"thanh_phan_chinh":"Collagen peptide Verisol 2,5 g mỗi khẩu phần 4 viên","lieu_dung":"Nhai 4 viên mỗi khẩu phần, dùng 1 lần mỗi ngày.","luu_y":["Collagen không phải nguồn đạm hoàn chỉnh, không dùng thay thế đạm trong bữa ăn.","Để xa tầm tay trẻ em."]},"sv-lutein-10":{"noi_dau":["Cả ngày dán mắt vào màn hình, tối về mắt mỏi rã rời.","Tuổi trung niên, nhìn xa nhìn gần đều thấy kém đi.","Bố mẹ lớn tuổi, con cái lo các vấn đề mắt về già."],"cong_dung":["Bổ sung lutein kèm zeaxanthin cho sức khỏe mắt.","Hỗ trợ sức khỏe mắt trong các tình trạng như đục thủy tinh thể theo nhãn.","Góp phần hỗ trợ mắt trước thoái hóa điểm vàng do tuổi tác.","Viên nang mềm, mỗi ngày dùng gọn nhẹ."],"thanh_phan_chinh":"Lutein 10 mg/viên, có zeaxanthin","lieu_dung":"Người lớn: uống 1 viên mỗi ngày, nên dùng cùng bữa ăn. Vui lòng đối chiếu hướng dẫn trên nhãn sau lọ.","luu_y":["Phụ nữ có thai, cho con bú hoặc người đang dùng thuốc nên hỏi nhân viên y tế trước khi dùng."]},"ks-coq10-200":{"noi_dau":["Leo vài tầng cầu thang đã thấy hụt hơi, mệt mỏi.","Tuổi 40 trở đi bắt đầu lo chuyện tim mạch của bản thân và bố mẹ.","Hay đau nửa đầu, mỗi cơn kèm buồn nôn rất khó chịu."],"cong_dung":["Bổ sung CoQ10 nguồn tự nhiên, 200 mg mỗi viên.","Hỗ trợ sức khỏe tim mạch và cung cấp chất chống oxy hóa.","Dùng dự phòng giúp giảm tần suất đau nửa đầu theo công bố trên nhãn.","Viên bao tan ở ruột, giảm khó chịu cho dạ dày nhạy cảm."],"thanh_phan_chinh":"Coenzyme Q10 (ubiquinone) 200 mg/viên","lieu_dung":"Uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của bác sĩ. Nên dùng ít nhất 3 tháng để thấy lợi ích.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc chống đông hoặc thuốc huyết áp.","Đi khám nếu cơn đau nửa đầu tăng lên hoặc buồn nôn, nôn kéo dài."]},"wn-omega369-180":{"noi_dau":["Ít ăn cá, lo cơ thể thiếu chất béo tốt cho tim và não.","Uống dầu cá hay bị ợ lên mùi tanh.","Làm việc trí óc nhiều, muốn chăm lo tim mạch và trí não cùng lúc."],"cong_dung":["Bổ sung omega-3, 6, 9 từ dầu cá, dầu hạt lanh và dầu lưu ly.","Hỗ trợ sức khỏe tim mạch và chức năng não theo công bố của hãng.","Góp phần duy trì sức khỏe tổng thể.","Viên bao tan ở ruột, hạn chế ợ tanh."],"thanh_phan_chinh":"Mỗi viên: dầu cá 400 mg (EPA 70 mg, DHA 45 mg), dầu hạt lanh 400 mg (ALA 200 mg), dầu lưu ly 400 mg","lieu_dung":"Người lớn: uống 2 viên x 3 lần/ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu đang dùng thuốc chống đông hoặc thuốc uống khác.","Để xa tầm tay trẻ em."]},"wn-acv-5000":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút.","Ăn xong bữa cơm là bụng đầy, khó tiêu.","Thích đồ ngọt, lại lo chuyện đường huyết khi có tuổi."],"cong_dung":["Bổ sung giấm táo lên men tự nhiên có 'giấm cái' kèm crom.","Hỗ trợ duy trì đường huyết bình thường theo công bố của hãng.","Góp phần hỗ trợ chuyển hóa tinh bột và chất béo.","Hỗ trợ tiêu hóa chất béo trong bữa ăn."],"thanh_phan_chinh":"Giấm táo tương đương 5000 mg nguyên liệu thô mỗi viên, kèm crom","lieu_dung":"Người lớn: uống 1–3 viên, 1 lần/ngày, nên uống cùng bữa ăn với một ly nước đầy, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có bệnh thận hoặc tiểu đường.","Không dùng khi có thai hoặc đang cho con bú."]},"jms-vitc-chew":{"noi_dau":["Con đi học về hay sụt sịt, cả nhà lây theo.","Ăn ít rau quả, lo cơ thể không đủ vitamin C.","Trẻ con sợ uống viên, người lớn thì hay quên."],"cong_dung":["Bổ sung vitamin C, 500 mg mỗi viên nhai.","Hỗ trợ hệ miễn dịch khỏe mạnh.","Giúp phòng ngừa thiếu vitamin C.","Viên nhai vị trái cây, dùng được cho trẻ từ 4 tuổi."],"thanh_phan_chinh":"Vitamin C (acid ascorbic) 500 mg/viên","lieu_dung":"Nhai, mỗi ngày 1 lần: người lớn 1–4 viên; 14–18 tuổi 1–3 viên; 9–13 tuổi 1–2 viên; 4–8 tuổi 1 viên.","luu_y":["Nhãn chỉ có liều cho trẻ từ 4 tuổi trở lên.","Để xa tầm tay trẻ em, bảo quản ở 15–25°C."]},"lv-wallet-damier":{"noi_dau":["Sợ mua phải hàng kém chất lượng khi chọn đồ da hiệu.","Muốn một chiếc ví lịch sự, dùng lâu năm mà không lỗi mốt.","Băn khoăn ví đẹp nhưng không đủ ngăn đựng thẻ, tiền."],"cong_dung":["Họa tiết ca-rô Damier Ebene nâu kinh điển, lịch lãm.","Canvas phủ bền, hạn chế trầy và bám bẩn khi dùng hằng ngày.","Kiểu gấp đôi gọn, vừa túi quần, túi áo vest.","Bên trong có các ngăn đựng thẻ và ngăn tiền."],"lieu_dung":"Dùng hằng ngày đựng tiền, thẻ; không nhét quá dày để ví giữ dáng. Bảo quản nơi khô ráo, tránh nước và nhiệt độ cao, lau bằng khăn mềm khô, cất trong túi vải khi không dùng."},"goli-acv":{"noi_dau":["Ăn uống điều độ mà cân nặng vẫn nhích lên từng chút","Muốn dùng giấm táo mỗi ngày nhưng ngại vị chua gắt khó uống","Bận rộn cả ngày, khó duy trì một thói quen tốt cho sức khỏe"],"cong_dung":["Bổ sung giấm táo dạng kẹo dẻo, dễ dùng hơn uống giấm trực tiếp","Hai viên kẹo tương đương một lượng giấm táo uống thường ngày theo hãng","Góp phần duy trì thói quen ăn uống lành mạnh khi kết hợp chế độ hợp lý","Thuần chay, không gluten, không biến đổi gen theo nhãn"],"thanh_phan_chinh":"Giấm táo kèm bột củ dền, bột lựu hữu cơ, vitamin B9 và B12","lieu_dung":"Người lớn nhai 1–2 viên kẹo, ngày 3 lần; nên dùng sau bữa ăn.","luu_y":["Nhãn Canada có biểu tượng cảnh báo sản phẩm nhiều đường, người cần kiểm soát đường huyết nên cân nhắc.","Phụ nữ có thai, cho con bú hoặc đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"jms-iron-28":{"noi_dau":["Hay mệt, hoa mắt khi đứng lên mà không rõ vì sao","Muốn bổ sung sắt nhưng sợ táo bón, nóng rát dạ dày","Kinh nguyệt hằng tháng khiến cơ thể dễ thiếu hụt sắt"],"cong_dung":["Hỗ trợ phòng ngừa tình trạng thiếu sắt theo công bố trên nhãn","Sắt dạng bisglycinate dịu nhẹ, thân thiện với dạ dày","Bổ sung thêm acid folic, vitamin B2, B12 và C","Viên nang thực vật, không gluten, không lactose"],"thanh_phan_chinh":"Sắt (ferrous bisglycinate) 28 mg, acid folic 400 mcg, B2 800 mcg, B12 8 mcg, vitamin C 60 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn. Uống cách các thuốc hoặc sản phẩm khác vài giờ.","luu_y":["Để xa tầm tay trẻ em: lượng sắt trong hộp đủ gây hại nghiêm trọng cho trẻ.","Uống cách thuốc khác vài giờ trước hoặc sau."]},"ks-glucosamine":{"noi_dau":["Lên xuống cầu thang đầu gối cứ ê ẩm, kêu lục cục","Sáng ngủ dậy khớp cứng, phải một lúc mới cử động thoải mái","Muốn tiếp tục đi bộ, làm việc nhà mà không bị đau khớp cản trở"],"cong_dung":["Hỗ trợ giảm đau khớp liên quan đến thoái hóa khớp theo công bố nhãn Canada","Góp phần bảo vệ sụn khớp trước sự hao mòn","Hỗ trợ duy trì sụn và khớp khỏe mạnh","Hỗ trợ làm dịu cảm giác nhức mỏi khớp"],"thanh_phan_chinh":"Glucosamine sulfate 500 mg, chondroitin sulfate 400 mg, MSM 400 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 3 lần cùng bữa ăn; dùng tối thiểu 4 tuần để thấy tác dụng, tránh uống lúc đi ngủ.","luu_y":["Nguồn gốc từ vỏ tôm, cua: người dị ứng hải sản có vỏ cần hỏi bác sĩ trước khi dùng.","Phụ nữ có thai hoặc cho con bú nên hỏi ý kiến bác sĩ.","Một số người có thể đầy hơi, táo bón hoặc khó tiêu nhẹ."]},"bragg-acv-ginger":{"noi_dau":["Muốn uống giấm táo mỗi sáng nhưng vị chua gắt khó nuốt","Tìm thức uống thanh nhẹ thay nước ngọt cho cả nhà","Ngại tự pha chế giấm, gừng, chanh mất thời gian mỗi ngày"],"cong_dung":["Giấm táo hữu cơ nguyên chất, chưa lọc, còn giữ con giấm","Pha sẵn cùng mật ong, nước cốt chanh và gừng, vị dễ uống hơn","Dùng pha nước uống hằng ngày hoặc trộn nước sốt, salad","Góp phần đa dạng thói quen uống lành mạnh trong gia đình"],"thanh_phan_chinh":"Giấm táo hữu cơ, mật ong hữu cơ, nước cốt chanh vàng, chanh xanh, gừng hữu cơ, chiết xuất cỏ ngọt","lieu_dung":"Lắc nhẹ trước khi dùng. Pha khoảng 2 thìa canh với 240 ml nước lọc hoặc nước có ga, khuấy đều; bảo quản lạnh sau khi mở.","luu_y":["Luôn pha loãng, không uống trực tiếp vì độ chua cao.","Có mật ong: không dùng cho trẻ dưới 1 tuổi."]},"wn-ubiquinol":{"noi_dau":["Bước qua tuổi 40, leo vài bậc thang đã thấy hụt hơi","Lo lắng cho sức khỏe tim mạch của bản thân và bố mẹ","Đang dùng thuốc mỡ máu, nghe nói cơ thể dễ thiếu CoQ10"],"cong_dung":["Hỗ trợ duy trì sức khỏe tim mạch theo công bố trên nhãn","Ubiquinol là dạng CoQ10 hoạt tính, cơ thể dễ hấp thu","Đóng vai trò chất chống oxy hóa, góp phần duy trì sức khỏe chung"],"thanh_phan_chinh":"Ubiquinol (CoQ10 dạng khử) 100 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 1–3 lần hoặc theo chỉ dẫn của bác sĩ; hỏi bác sĩ nếu dùng quá 4 tuần.","luu_y":["Hỏi bác sĩ trước khi dùng nếu có thai, cho con bú, đang dùng thuốc huyết áp, thuốc chống đông hoặc hóa trị.","Để xa tầm tay trẻ em."]},"redwin-vite":{"noi_dau":["Da tay chân khô ráp, nứt nẻ mỗi khi trời hanh","Da nhạy cảm, dùng kem lạ là dễ ngứa rát","Muốn một hũ kem dưỡng to, cả nhà dùng chung tiết kiệm"],"cong_dung":["Dưỡng ẩm cho da khô, da nhạy cảm","Chứa vitamin E tự nhiên và dầu hoa anh thảo","Giúp da mềm mại, dễ chịu hơn khi thời tiết khô hanh","Dùng được cho mặt và toàn thân"],"thanh_phan_chinh":"Vitamin E tự nhiên (từ mầm lúa mì) và dầu hoa anh thảo","lieu_dung":"Thoa đều lên da sạch, khô và massage đến khi thấm; dùng hằng ngày hoặc khi cần, nhất là sau khi tắm, rửa tay hoặc ra nắng gió.","luu_y":["Chỉ dùng ngoài da, tránh để kem dính vào mắt.","Bảo quản dưới 30°C."]},"nb-hsn-softgel":{"noi_dau":["Tóc rụng nhiều mỗi lần gội, chải đầu","Móng tay mỏng, dễ gãy, tách lớp","Da xỉn màu, thiếu sức sống dù đã chăm dưỡng bên ngoài"],"cong_dung":["Bổ sung biotin hàm lượng cao cùng nhóm vitamin cho tóc, da, móng","Có vitamin C và E chống oxy hóa, thêm hyaluronic acid","Bổ sung dầu argan và collagen thủy phân","Viên nang mềm dạng lỏng, giải phóng nhanh"],"thanh_phan_chinh":"Biotin 5.000 mcg, vitamin A, C, E, nhóm B, dầu argan 25 mg, hyaluronic acid 30 mg mỗi 3 viên","lieu_dung":"Người lớn uống 3 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Có thai, cho con bú, đang dùng thuốc, sắp phẫu thuật hoặc sắp xét nghiệm máu cần hỏi bác sĩ trước khi dùng.","Có thành phần từ đậu nành và hạt cây (argan)."]},"ks-fish-oil-wild":{"noi_dau":["Bữa cơm gia đình ít khi có cá biển","Lo lắng chỉ số mỡ máu khi khám sức khỏe định kỳ","Muốn chăm tim mạch cho bố mẹ mà không biết bắt đầu từ đâu"],"cong_dung":["Hỗ trợ sức khỏe tim mạch theo công bố của hãng","Hỗ trợ duy trì triglyceride trong ngưỡng bình thường","Dầu cá tự nhiên từ cá đánh bắt hoang dã vùng Alaska","Được USP kiểm chứng chất lượng"],"thanh_phan_chinh":"Dầu cá 1400 mg, trong đó omega-3 330 mg (EPA + DHA 230 mg) mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày với một ly nước đầy, tốt nhất cùng bữa ăn.","luu_y":["Có nguồn gốc từ cá, người dị ứng cá không dùng.","Người đang dùng thuốc chống đông hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng."]},"tn-lutein-140":{"noi_dau":["Nhìn điện thoại, máy tính cả ngày, tối về mắt mỏi rát","Đọc chữ nhỏ ngày càng khó, phải đưa ra xa mới thấy","Lo đôi mắt bố mẹ yếu dần theo tuổi"],"cong_dung":["Có thể hỗ trợ thị lực khỏe mạnh theo công bố trên nhãn","Có thể giúp cải thiện độ nhạy thị giác","Hỗ trợ bảo vệ mắt khi tiếp xúc ánh sáng xanh từ màn hình","Tỷ lệ lutein và zeaxanthin 5:1 từ hoa cúc vạn thọ"],"thanh_phan_chinh":"Lutein 25 mg và đồng phân zeaxanthin 5 mg (Lutemax 2020) mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Có thành phần từ đậu nành."]},"sr-d3-k2":{"noi_dau":["Làm việc trong nhà cả ngày, ít khi ra nắng","Lo xương yếu dần khi bước vào tuổi tiền mãn kinh","Uống canxi mà không chắc cơ thể có dùng được hiệu quả"],"cong_dung":["Hỗ trợ sức khỏe xương và hệ miễn dịch theo công bố của hãng","Vitamin D3 hỗ trợ cơ thể chuyển hóa canxi","Vitamin K2 (MK-7) góp phần đưa canxi về xương","Thuần chay, D3 từ địa y, kèm dầu dừa MCT giúp hấp thu"],"thanh_phan_chinh":"Vitamin D3 125 mcg (5000 IU) và vitamin K2 dạng MK-7 100 mcg mỗi viên","lieu_dung":"Người lớn uống 1 viên mỗi ngày cùng bữa ăn, hoặc theo chỉ dẫn của chuyên gia y tế.","luu_y":["Không dùng chung với các sản phẩm vitamin D liều cao khác.","Người đang dùng thuốc chống đông (như warfarin), có thai, cho con bú hoặc có bệnh lý cần hỏi bác sĩ trước khi dùng.","Không dùng quá liều khuyến cáo."]},"olay-dark-spot":{"noi_dau":["Da tay, chân sạm màu, lốm đốm sau nhiều năm đi nắng","Vùng khuỷu tay, đầu gối thâm sạm làm ngại mặc váy áo ngắn","Dưỡng thể thường chỉ ẩm, không thấy da đều màu hơn"],"cong_dung":["Hỗ trợ làm mờ đốm sậm màu trên da cơ thể theo công bố hãng","AHA tẩy tế bào chết nhẹ, giúp bề mặt da mịn và đều màu hơn","Vitamin C và niacinamide góp phần giúp da trông sáng hơn","Dưỡng ẩm cho da toàn thân hằng ngày"],"thanh_phan_chinh":"AHA, vitamin C và niacinamide","lieu_dung":"Thoa đều lên da cơ thể sạch mỗi ngày, tốt nhất sau khi tắm; kết hợp kem chống nắng khi ra ngoài.","luu_y":["Sản phẩm có AHA có thể làm da nhạy cảm hơn với ánh nắng: dùng kem chống nắng và hạn chế phơi nắng trong thời gian dùng và một tuần sau đó.","Tránh để dính vào mắt, nếu dính rửa sạch bằng nước."]},"olly-sleep":{"noi_dau":["Nằm trằn trọc mãi mới chợp mắt được","Đầu óc cứ nghĩ chuyện nhà, chuyện cửa hàng đến khuya","Sáng dậy uể oải vì giấc ngủ chập chờn"],"cong_dung":["Hỗ trợ giấc ngủ, giúp dễ đi vào giấc ngủ hơn","Melatonin góp phần điều chỉnh nhịp ngủ – thức","L-theanine kèm thảo mộc hỗ trợ thư giãn trước khi ngủ","Dạng kẹo dẻo vị mâm xôi đen, dễ dùng"],"thanh_phan_chinh":"Melatonin 3 mg và L-theanine 100 mg mỗi 2 viên, kèm thảo mộc","lieu_dung":"Người lớn nhai 2 viên mỗi ngày một lần, vào lúc hoặc trước giờ đi ngủ.","luu_y":["Không lái xe hoặc vận hành máy móc trong 5 giờ sau khi dùng melatonin.","Hỏi chuyên gia y tế nếu dùng quá 4 tuần.","Phụ nữ có thai, cho con bú và trẻ em không tự ý dùng."]},"jms-biotin-gummy":{"noi_dau":["Tóc mỏng dần, chân tóc thưa thấy rõ khi buộc lên","Móng tay giòn, hay gãy, tách lớp","Ngại nuốt viên thuốc to mỗi ngày"],"cong_dung":["Hỗ trợ phòng ngừa thiếu hụt biotin theo công bố nhãn","Hỗ trợ tóc, da và móng khỏe mạnh","Hỗ trợ cải thiện móng tay giòn, dễ gãy","Bổ sung vitamin C và E, vị trái cây dễ dùng"],"thanh_phan_chinh":"Biotin 1.250 mcg, vitamin C 7,5 mg, vitamin E 7,5 IU mỗi viên","lieu_dung":"Người lớn nhai 2 viên mỗi ngày.","luu_y":["Phụ nữ có thai hoặc cho con bú nên hỏi chuyên gia y tế trước khi dùng.","Biotin có thể làm sai lệch một số xét nghiệm, hãy báo bác sĩ khi đi xét nghiệm.","Hỏi chuyên gia y tế nếu dùng quá 1 tháng."]},"citracal-max":{"noi_dau":["Bước sang tuổi 45, lo xương giòn dần mà không hay biết","Uống canxi loại thường hay bị đầy bụng, táo bón","Không nhớ nổi phải uống canxi trước hay sau bữa ăn"],"cong_dung":["Bổ sung canxi citrate và vitamin D3 hỗ trợ sức khỏe xương","Kèm kẽm, đồng, mangan góp phần hỗ trợ xương chắc khỏe","Canxi citrate dịu nhẹ với dạ dày theo công bố hãng","Uống được lúc no hoặc lúc đói"],"thanh_phan_chinh":"Canxi citrate và vitamin D3 25 mcg (1000 IU) mỗi 2 viên, kèm kẽm 5,5 mg, đồng 0,45 mg, mangan 1,15 mg","lieu_dung":"Người lớn uống 2 viên, ngày 2 lần, cùng hoặc không cùng bữa ăn, hoặc theo chỉ dẫn của chuyên gia y tế.","luu_y":["Phụ nữ có thai, cho con bú, người đang dùng thuốc hoặc có bệnh lý nên hỏi chuyên gia y tế trước khi dùng.","Chỉ dành cho người lớn, để xa tầm tay trẻ em; không dùng quá liều khuyến cáo."]},"an-liquid-collagen":{"noi_dau":["Soi gương thấy da kém căng, nếp nhăn khóe mắt rõ hơn","Uống collagen bột hay viên thấy bất tiện, khó duy trì","Muốn chăm da từ bên trong mà không mất nhiều thời gian"],"cong_dung":["Bổ sung collagen thủy phân dạng nước, pha uống tiện lợi","Bổ sung biotin hỗ trợ tóc, da và móng","Kèm chiết xuất trái cây chống oxy hóa","Góp phần hỗ trợ làn da đủ ẩm, tươi tắn"],"thanh_phan_chinh":"Collagen 4.000 mg và biotin 500 mcg mỗi ống (theo hộp bản Canada)","lieu_dung":"Mỗi ngày dùng 1 ống: lắc đều, bẻ nắp rồi pha vào khoảng 500 ml nước, khuấy đều; không uống trực tiếp từ ống.","luu_y":["Không dùng cho phụ nữ có thai, cho con bú hoặc người dưới 18 tuổi.","Người đang dùng thuốc hoặc có bệnh lý nên hỏi bác sĩ trước khi dùng.","Không dùng nếu ống đã bị mở."]},"sv-omega3-1200":{"noi_dau":["Hay quên trước quên sau, vừa cầm điện thoại đã quên định làm gì","Làm việc cả ngày, chiều về đầu óc mệt, khó tập trung","Cả nhà ít ăn cá, lo thiếu omega-3"],"cong_dung":["Hỗ trợ sức khỏe nhận thức và chức năng não theo công bố trên nhãn","Bổ sung omega-3 từ dầu cá","Góp phần bù đắp khi bữa ăn ít cá biển"],"thanh_phan_chinh":"Dầu cá 1200 mg mỗi viên","lieu_dung":"Người lớn uống 1 viên, ngày 3 lần, tốt nhất cùng bữa ăn.","luu_y":["Người dị ứng cá, đang dùng thuốc chống đông, có thai hoặc cho con bú nên hỏi bác sĩ trước khi dùng."]},"pantene-10-sh":{"noi_dau":["Tóc nhuộm, uốn nhiều lần nên khô xơ, dễ gãy","Gội xong tóc rối, chải đau và rụng nhiều","Nhà đông người, chai dầu gội nhỏ dùng mấy hôm đã hết"],"cong_dung":["Dưỡng ẩm, gỡ rối và giúp tóc mượt hơn","Hỗ trợ bảo vệ màu tóc nhuộm và bảo vệ tóc khỏi nhiệt","Góp phần làm tóc chắc khỏe, bóng hơn, phục hồi hư tổn bề mặt","Có keratin, vitamin E, dầu dừa, tiền vitamin B5; không paraben, không phẩm màu"],"thanh_phan_chinh":"Keratin thủy phân, dầu dừa, vitamin E, panthenol (tiền vitamin B5)","lieu_dung":"Làm ướt tóc, lấy lượng dầu gội vừa đủ xoa đều lên tóc và da đầu tạo bọt, sau đó xả sạch; dùng kèm dầu xả cùng dòng để tóc mềm hơn.","luu_y":["Tránh để dầu gội dính vào mắt, nếu dính rửa sạch bằng nước."]},"ks-hsn-gummy":{"noi_dau":["Tóc rụng nhiều sau sinh hoặc sau những tháng căng thẳng","Móng tay mỏng, hay gãy khi làm việc nhà","Ngại uống viên nang to, muốn dạng kẹo dễ dùng hằng ngày"],"cong_dung":["Hỗ trợ tóc dày hơn theo công bố trên nhãn","Hỗ trợ móng chắc khỏe hơn","Góp phần giúp làn da khỏe mạnh","Dạng kẹo dẻo vị dâu, dễ dùng"],"lieu_dung":"Dùng theo đúng liều in trên nhãn chai; không dùng quá liều khuyến cáo.","luu_y":["Sản phẩm có biotin: báo bác sĩ khi đi xét nghiệm máu.","Phụ nữ có thai, cho con bú nên hỏi ý kiến chuyên gia y tế trước khi dùng."]},"349cdad5":{"noi_dau":["Nhìn màn hình lâu, mắt khô rát như có cát","Ngồi phòng điều hòa cả ngày, mắt cay và mỏi","Sợ thuốc nhỏ mắt có chất bảo quản gây kích ứng khi dùng nhiều lần"],"cong_dung":["Làm dịu tạm thời cảm giác khô, rát, kích ứng mắt","Bôi trơn, giữ ẩm bề mặt mắt","Không chất bảo quản, ống đơn liều dùng một lần","Được khuyên dùng cho tình trạng khô mắt sau LASIK theo hướng dẫn bác sĩ"],"thanh_phan_chinh":"Carboxymethylcellulose natri 0,5%","lieu_dung":"Vặn bẻ nắp ống, nhỏ 1–2 giọt vào mắt khi cần, sau đó bỏ ống. Khô mắt sau phẫu thuật (như LASIK) dùng theo chỉ dẫn bác sĩ mắt.","luu_y":["Ngưng dùng và hỏi bác sĩ nếu đau mắt, thay đổi thị lực, đỏ hoặc kích ứng kéo dài, hoặc triệu chứng nặng hơn hay kéo dài quá 72 giờ.","Không dùng lại ống đã mở, không để đầu ống chạm vào mắt; không dùng nếu dung dịch đổi màu hoặc vẩn đục.","Để xa tầm tay trẻ em, nếu nuốt phải cần đến cơ sở y tế ngay."]},"ks-calcium-plus":{"noi_dau":["Bước sang tuổi 40, đi cầu thang nhiều đã thấy đầu gối mỏi rã.","Ăn uống bận rộn, ít uống sữa nên lo cả nhà thiếu canxi.","Muốn bổ sung canxi cho bố mẹ nhưng ngại loại phải uống nhiều viên mỗi ngày."],"cong_dung":["Bổ sung canxi và vitamin D3 hỗ trợ phát triển, duy trì xương và răng.","Vitamin D góp phần giúp cơ thể hấp thu và sử dụng canxi tốt hơn.","Hỗ trợ duy trì chức năng cơ bình thường.","Cùng chế độ ăn lành mạnh và vận động đều, góp phần giảm nguy cơ loãng xương."],"thanh_phan_chinh":"Canxi nguyên tố 600 mg + vitamin D3 800 IU mỗi viên, kèm khoáng chất","lieu_dung":"Người lớn từ 19 tuổi: uống 1 viên mỗi ngày cùng bữa ăn, uống cách các thuốc khác vài giờ, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang dùng thuốc chống đông máu.","Không dùng nếu niêm phong dưới nắp bị rách; để xa tầm tay trẻ em."]},"cetaphil-oily":{"noi_dau":["Mới rửa mặt buổi sáng mà đến trưa da đã bóng dầu.","Lỗ chân lông vùng mũi, má cứ to dần, trang điểm khó tiệp.","Sợ sữa rửa mặt tẩy mạnh làm da căng rát, dễ kích ứng."],"cong_dung":["Làm sạch dịu nhẹ, loại bỏ dầu thừa trên da.","Giúp lỗ chân lông trông se khít hơn.","Chứa niacinamide và pro-vitamin B5, hỗ trợ giữ hàng rào bảo vệ da.","Phù hợp da hỗn hợp, da dầu và cả da nhạy cảm."],"thanh_phan_chinh":"Niacinamide (vitamin B3) và pro-vitamin B5 (panthenol)","lieu_dung":"Lấy một lượng nhỏ lên da mặt đã làm ướt, massage nhẹ nhàng rồi rửa sạch bằng nước; dùng sáng và tối.","luu_y":["Chỉ dùng ngoài da, tránh để sản phẩm dính vào mắt."]},"wn-collagen30":{"noi_dau":["Soi gương thấy vùng đuôi mắt xuất hiện nếp nhăn nhỏ.","Da mặt khô ráp, thoa kem dưỡng mà vẫn thiếu độ ẩm.","Tóc dễ gãy, móng tay mỏng và hay tách lớp."],"cong_dung":["Hỗ trợ cải thiện độ ẩm và độ đàn hồi của da.","Góp phần làm giảm nếp nhăn vùng mắt và nếp nhăn nhỏ trên mặt.","Hỗ trợ tóc chắc khỏe và móng khỏe đẹp.","Kết hợp collagen peptide Verisol với ceramide thực vật, axit hyaluronic và vitamin C."],"thanh_phan_chinh":"Collagen peptide Verisol 625 mg, ceramide thực vật 7,5 mg, axit hyaluronic 5 mg mỗi viên, kèm biotin","lieu_dung":"Người lớn: uống 2 viên x 2 lần mỗi ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai hoặc cho con bú.","Có thể gây khó chịu nhẹ ở dạ dày; biotin có thể ảnh hưởng kết quả xét nghiệm, hãy báo bác sĩ.","Có chiết xuất từ hạt lúa mì, người dị ứng lúa mì cần lưu ý."]},"ks-d3-2x360":{"noi_dau":["Làm việc trong nhà cả ngày, hầu như không ra nắng.","Lo xương khớp yếu dần theo tuổi mà không biết bổ sung gì.","Hay bị ốm vặt mỗi khi giao mùa, cả nhà thay nhau mệt."],"cong_dung":["Bổ sung vitamin D3, một vitamin thiết yếu cho cơ thể.","Hỗ trợ duy trì xương và răng chắc khỏe.","Góp phần giúp hấp thu và sử dụng canxi, phốt pho.","Hỗ trợ chức năng miễn dịch."],"thanh_phan_chinh":"Vitamin D3 25 mcg (1000 IU) mỗi viên","lieu_dung":"Người lớn: uống 1 viên mỗi ngày.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách.","Bảo quản ở 15–25°C, để xa tầm tay trẻ em."]},"ks-lutein-25":{"noi_dau":["Nhìn màn hình điện thoại, máy tính cả ngày, tối về mắt mỏi nhức.","Tuổi càng cao, đọc chữ nhỏ càng thấy mờ và chói.","Lo cho mắt của bố mẹ khi tuổi già mà chưa biết bắt đầu từ đâu."],"cong_dung":["Hỗ trợ sức khỏe mắt nhờ giúp lọc ánh sáng xanh.","Hỗ trợ mắt trong các tình trạng như đục thủy tinh thể, thoái hóa điểm vàng tuổi già.","Góp phần cải thiện mật độ sắc tố điểm vàng, theo nghiên cứu hãng công bố.","Chiết xuất từ hoa cúc vạn thọ, dùng 1 viên mỗi ngày tiện lợi."],"thanh_phan_chinh":"Lutein 25 mg, zeaxanthin và meso-zeaxanthin mỗi loại 2,5 mg mỗi viên","lieu_dung":"Uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai hoặc cho con bú.","Không dùng nếu niêm phong dưới nắp bị rách."]},"ricola":{"noi_dau":["Nói nhiều cả ngày, chiều về cổ họng khô rát.","Thời tiết đổi mùa là cổ họng ngứa, ho húng hắng.","Muốn có viên kẹo ngậm dễ chịu mang theo trong túi xách."],"cong_dung":["Kẹo ngậm làm dịu cổ họng, hỗ trợ giảm ho thông thường.","Kết hợp tinh dầu bạc hà và hỗn hợp thảo mộc vùng núi Thụy Sĩ.","Mang lại cảm giác mát dịu, thơm vị cherry hoặc chanh bạc hà.","Vị Lemon Mint không thêm đường, có bổ sung vitamin C."],"thanh_phan_chinh":"Menthol từ bạc hà và chiết xuất hỗn hợp thảo mộc (tía tô đất, cỏ xạ hương, xô thơm, hoa đoạn…)","lieu_dung":"Người lớn và trẻ từ 12 tuổi: ngậm tan từ từ từng viên, không nhai; vị Cherry ngậm 1 viên mỗi 1–2 giờ. Không quá 10 viên mỗi ngày.","luu_y":["Ngưng dùng và hỏi ý kiến nhân viên y tế nếu ho nặng hơn, kéo dài quá 7 ngày hoặc kèm sốt.","Vị Lemon Mint có chất tạo ngọt aspartame, người bệnh phenylketon niệu không nên dùng."]},"nb-hsn-gummy":{"noi_dau":["Mỗi lần chải đầu lại thấy tóc rụng vương đầy lược.","Móng tay mỏng, dễ gãy, sơn móng cũng không giữ được lâu.","Ngại uống viên thuốc to, muốn loại dễ dùng mỗi ngày."],"cong_dung":["Bổ sung biotin hàm lượng cao hỗ trợ tóc, da và móng.","Có vitamin A cùng vitamin C, E chống oxy hóa hỗ trợ làn da.","Dạng kẹo dẻo vị dâu dễ nhai, dễ duy trì mỗi ngày.","Không biến đổi gen (Non-GMO)."],"thanh_phan_chinh":"Biotin 6.000 mcg mỗi 2 viên kẹo, kèm vitamin A, C, E","lieu_dung":"Người lớn: nhai 2 viên kẹo mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Phụ nữ mang thai, cho con bú, người có bệnh lý hoặc đang dùng thuốc nên hỏi bác sĩ trước khi dùng.","Biotin liều cao có thể làm sai lệch một số xét nghiệm máu, hãy báo bác sĩ khi đi xét nghiệm."]},"ks-cal-citrate":{"noi_dau":["Hay bị chuột rút bắp chân lúc nửa đêm.","Dạ dày yếu, uống canxi thường hay thấy đầy bụng khó chịu.","Phụ nữ tuổi tiền mãn kinh lo xương ngày một yếu đi."],"cong_dung":["Bổ sung canxi citrate hỗ trợ xương và răng chắc khỏe.","Vitamin D3 góp phần giúp hấp thu canxi.","Magie và kẽm hỗ trợ quá trình tạo xương, co cơ bình thường.","Kẽm góp phần hỗ trợ hệ miễn dịch."],"thanh_phan_chinh":"Canxi (citrate) 500 mg, magie 80 mg kèm kẽm và vitamin D3 trong mỗi 2 viên","lieu_dung":"Uống 2 viên mỗi ngày, hoặc theo khuyến nghị của bác sĩ.","luu_y":["Người đang dùng thuốc hoặc có bệnh lý nên hỏi ý kiến bác sĩ trước khi dùng."]},"sr-multi-collagen":{"noi_dau":["Da mặt kém căng mịn hơn hẳn so với vài năm trước.","Tóc khô xơ, mỏng dần, buộc tóc thấy nhỏ hẳn đi.","Muốn uống collagen nhưng ngại pha bột mỗi sáng."],"cong_dung":["Hỗ trợ tóc và da khỏe mạnh.","Kết hợp 5 loại collagen (I, II, III, V, X) trong một viên nang.","Bổ sung biotin, axit hyaluronic và vitamin C hỗ trợ làn da.","Không gluten, không đậu nành, không biến đổi gen."],"thanh_phan_chinh":"Hỗn hợp Multi Collagen 1.600 mg và biotin 3.000 mcg mỗi 3 viên","lieu_dung":"Người lớn: uống 3 viên mỗi ngày, có thể uống cùng hoặc không cùng bữa ăn.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, có bệnh lý hoặc đang dùng thuốc.","Biotin có thể ảnh hưởng kết quả xét nghiệm, hãy báo bác sĩ khi đi xét nghiệm."]},"ks-vitc-1000":{"noi_dau":["Thời tiết thay đổi là người mệt mỏi, dễ cảm cúm.","Công việc căng thẳng, ăn ít rau quả nên lo thiếu vitamin.","Muốn bổ sung vitamin C cho cả nhà mà tiện, đỡ tốn kém."],"cong_dung":["Bổ sung vitamin C, chất chống oxy hóa giúp duy trì sức khỏe tốt.","Dạng giải phóng chậm, phóng thích vitamin C từ từ trong ngày.","Có thêm chiết xuất quả tầm xuân (rose hips).","Hộp lớn 500 viên dùng được lâu dài."],"thanh_phan_chinh":"Vitamin C 1000 mg giải phóng chậm, tầm xuân 40 mg mỗi viên","lieu_dung":"Người từ 9 tuổi trở lên: uống 1 viên mỗi ngày, hoặc theo chỉ dẫn của nhân viên y tế.","luu_y":["Không dùng nếu niêm phong dưới nắp bị rách hoặc mất.","Bảo quản ở 15–30°C."]},"tn-cinsulin":{"noi_dau":["Đi khám sức khỏe, bác sĩ dặn phải để ý đường huyết.","Đã cố bớt đồ ngọt, cơm trắng mà vẫn lo lắng.","Muốn tìm thêm giải pháp tự nhiên hỗ trợ bên cạnh ăn uống điều độ."],"cong_dung":["Hỗ trợ duy trì đường huyết khỏe mạnh trong ngưỡng bình thường.","Góp phần hỗ trợ chuyển hóa đường.","Chiết xuất quế bằng nước theo công nghệ được cấp bằng sáng chế.","Bổ sung thêm crom và vitamin D3."],"thanh_phan_chinh":"Chiết xuất vỏ quế 500 mg, crom 400 mcg, vitamin D3 500 IU mỗi 2 viên","lieu_dung":"Uống 2 viên một lần mỗi ngày với nước, trong bữa ăn.","luu_y":["Không dùng cho phụ nữ mang thai, cho con bú hoặc người dị ứng quế.","Người tiểu đường, hạ đường huyết chỉ dùng khi có theo dõi của bác sĩ.","Hỏi ý kiến bác sĩ nếu đang dùng thuốc hoặc có bệnh lý."]},"nb-vite-400":{"noi_dau":["Da khô, kém tươi tắn dù đã chăm dưỡng ngoài.","Ăn uống thất thường, lo thiếu vitamin chống oxy hóa.","Muốn bổ sung vitamin E loại uống 1 viên mỗi ngày cho tiện."],"cong_dung":["Bổ sung vitamin E, yếu tố góp phần duy trì sức khỏe tốt.","Vitamin E là chất chống oxy hóa cho cơ thể.","Không chứa chất bảo quản.","Hộp lớn 200 viên dùng được lâu."],"thanh_phan_chinh":"Vitamin E (dl-alpha tocopheryl acetat) 400 IU mỗi viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi ngày, tốt nhất cùng bữa ăn.","luu_y":["Không dùng nếu đang mang thai hoặc cho con bú (theo nhãn Canada).","Người đang dùng thuốc nên hỏi ý kiến bác sĩ trước khi dùng."]},"yt-k2d3-gummy":{"noi_dau":["Lo xương yếu dần theo tuổi nhưng ngại uống thêm viên thuốc.","Ít ra nắng, sợ cơ thể thiếu vitamin D.","Muốn bổ sung vitamin mà không nạp thêm đường."],"cong_dung":["Hỗ trợ sức khỏe xương và hệ miễn dịch.","Kết hợp vitamin D3 và vitamin K2 dạng MK-7.","Kẹo dẻo vị đào, không đường, dễ dùng mỗi ngày."],"lieu_dung":"Người lớn: nhai 1 viên kẹo mỗi ngày.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang dùng thuốc (đặc biệt thuốc chống đông) hoặc có bệnh lý.","Không dùng khi mang thai, cho con bú; không dành cho người dưới 18 tuổi."]},"jms-cal-mag-zinc":{"noi_dau":["Hay bị chuột rút, mỏi cơ sau một ngày đứng nhiều.","Phụ nữ sau sinh, tiền mãn kinh lo xương ngày càng yếu.","Muốn một viên bổ sung đủ canxi, magie, kẽm cho gọn."],"cong_dung":["Hỗ trợ phát triển và duy trì xương, răng.","Góp phần duy trì chức năng cơ bình thường, kể cả cơ tim.","Kẽm hỗ trợ miễn dịch, da, tóc và móng khỏe.","Cùng vitamin D và vận động, góp phần giảm nguy cơ mất xương về sau."],"thanh_phan_chinh":"Canxi 333 mg, magie 167 mg, kẽm 17 mg mỗi viên","lieu_dung":"Người lớn: uống 1–3 viên mỗi ngày cùng bữa ăn, cách các thuốc khác vài giờ.","luu_y":["Một số người có thể bị tiêu chảy.","Bổ sung kẽm có thể gây thiếu đồng."]},"ks-omega3-1300":{"noi_dau":["Tuổi trung niên, đi khám thấy mỡ máu bắt đầu nhích lên.","Hay quên, làm việc lâu là đầu óc mệt mỏi.","Uống dầu cá loại thường hay bị ợ tanh khó chịu."],"cong_dung":["Hỗ trợ chức năng tim mạch và não bộ.","Góp phần hỗ trợ giảm triglyceride trong máu.","Hỗ trợ kháng viêm, cung cấp axit béo omega-3.","Viên bao tan trong ruột giúp hạn chế ợ tanh."],"thanh_phan_chinh":"Dầu cá 1300 mg với EPA 450 mg và DHA 300 mg mỗi viên","lieu_dung":"Người lớn từ 18 tuổi: uống 1 viên mỗi ngày cho tim mạch, não bộ; 2 viên mỗi ngày để hỗ trợ giảm triglyceride, hoặc theo chỉ dẫn bác sĩ.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, dùng thuốc chống đông hoặc có bệnh lý."]},"sr-omega3-150":{"noi_dau":["Ít ăn cá biển, lo cả nhà thiếu omega-3.","Mỗi ngày phải uống nhiều viên dầu cá thấy ngại.","Sợ dầu cá kém chất lượng, không rõ nguồn gốc."],"cong_dung":["Bổ sung omega-3 nồng độ cao chỉ với 1 viên mỗi ngày.","Hỗ trợ sức khỏe tim mạch, não bộ và thị lực.","Dầu cá đánh bắt tự nhiên, nguồn khai thác bền vững.","Không biến đổi gen, được kiểm nghiệm bởi bên thứ ba."],"thanh_phan_chinh":"Dầu cá 1250 mg, tổng omega-3 1055 mg mỗi viên","lieu_dung":"Người lớn: uống 1 viên mỗi ngày cùng bữa ăn, hoặc theo khuyến nghị của chuyên gia y tế.","luu_y":["Hỏi ý kiến bác sĩ trước khi dùng nếu đang mang thai, cho con bú, dùng thuốc hoặc có bệnh lý."]},"pantene-10-cn":{"noi_dau":["Tóc nhuộm, uốn nhiều lần nên khô xơ, dễ rối.","Gội xong tóc bết hoặc xù, mất cả buổi để chải.","Muốn một chai dùng lâu cho cả nhà mà vẫn mượt tóc."],"cong_dung":["Công thức 10 trong 1: dưỡng ẩm, gỡ rối, làm mượt và làm mềm tóc.","Hỗ trợ bảo vệ màu tóc nhuộm và bảo vệ tóc khỏi nhiệt.","Giúp tóc chắc khỏe, bóng hơn, phục hồi hư tổn.","Chứa keratin, vitamin E, dầu dừa và pro-vitamin B5."],"thanh_phan_chinh":"Keratin thủy phân, dầu dừa, vitamin E, pro-vitamin B5","lieu_dung":"Sau khi gội, thoa dầu xả lên tóc ướt từ thân đến ngọn, để khoảng 1–3 phút rồi xả sạch với nước.","luu_y":["Tránh để sản phẩm dính vào mắt; nếu dính, rửa sạch bằng nước."]},"tylenol-ultra":{"noi_dau":["Cơn đau đầu ập đến giữa giờ làm, khó tập trung.","Đau nửa đầu khiến cả ngày mệt mỏi, chỉ muốn nằm.","Cần sẵn thuốc trong nhà khi người thân bị sốt."],"cong_dung":["Giảm tạm thời đau nhẹ đến vừa do đau đầu, đau nửa đầu.","Hạ sốt.","Caffeine giúp tăng hiệu quả giảm đau đầu của acetaminophen.","Viên eZ Tabs nhỏ, dễ nuốt."],"thanh_phan_chinh":"Acetaminophen (paracetamol) 500 mg + caffeine 65 mg mỗi viên","lieu_dung":"Người lớn và trẻ từ 12 tuổi: uống 1 viên mỗi 4–6 giờ; nếu không đỡ, liều sau có thể uống 2 viên. Không quá 8 viên trong 24 giờ.","luu_y":["Quá liều có thể gây tổn thương gan nghiêm trọng; không dùng chung với thuốc khác chứa acetaminophen/paracetamol, hỏi bác sĩ nếu uống rượu thường xuyên hoặc bệnh gan, thận.","Tránh dùng thêm đồ uống, thuốc có caffeine; hỏi bác sĩ nếu tăng huyết áp, glôcôm, đang mang thai hoặc cho con bú.","Đi khám nếu triệu chứng kéo dài quá 5 ngày; để xa tầm tay trẻ em."]},"ad728e60":{"noi_dau":["Nhìn màn hình lâu, mắt khô rát và cộm như có cát.","Ngồi phòng máy lạnh cả ngày, chiều về mắt đỏ, mỏi.","Đi đường gió bụi, nắng gắt khiến mắt cay khó chịu."],"cong_dung":["Giảm tạm thời cảm giác nóng rát, kích ứng, khó chịu do khô mắt.","Làm dịu mắt khi tiếp xúc gió hoặc nắng.","Bộ nhiều lọ tiện để ở nhà, văn phòng, ô tô và mang theo."],"thanh_phan_chinh":"Carboxymethylcellulose natri 0,5%","lieu_dung":"Nhỏ 1–2 giọt vào mắt bị khô khi cần.","luu_y":["Không chạm đầu lọ vào bất kỳ bề mặt nào; đậy nắp sau khi dùng; không dùng nếu dung dịch đổi màu hoặc vẩn đục.","Ngưng dùng và đi khám nếu đau mắt, thay đổi thị lực, mắt đỏ kéo dài hoặc không đỡ sau 72 giờ.","Để xa tầm tay trẻ em; nếu nuốt phải, đến cơ sở y tế ngay."]}};
